mapper.select:
SELECT z.id, z.warehouse_id, z.zone_code, z.zone_name, z.zone_type, z.sort_order, z.remark FROM yms_yard_zone z WHERE z.deleted = 0
AND z.warehouse_id = #{bo.warehouseId}
AND z.zone_code LIKE CONCAT('%', #{bo.zoneCode}, '%')
AND z.zone_type = #{bo.zoneType}
ORDER BY z.sort_order ASC, z.zone_code ASC
